using Astrea.BattleActions;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class ActionFaceInstance2D : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private Image actionImage;

	[SerializeField]
	private TextMeshProUGUI actionValue;

	private Color defaultColor;

	private BattleAction battleAction;

	public Image ActionImage => actionImage;

	public TextMeshProUGUI ActionValue => actionValue;

	public void Initialize(BattleAction battleAction, string actionAmount, bool empowered, CompendiumItemState compendiumItemState = CompendiumItemState.Discovered)
	{
		if (ReferenceSingleton<AssetsReference>.Instance.GameController.IsDailyRun)
		{
			compendiumItemState = CompendiumItemState.Discovered;
		}
		_ = battleAction == null;
		BaseBattleActionData baseBattleActionData = battleAction.BaseBattleActionData;
		this.battleAction = battleAction;
		_ = baseBattleActionData == null;
		defaultColor = (baseBattleActionData.EnableColorReference ? baseBattleActionData.colorReference.Value : baseBattleActionData.ActionColor);
		_ = actionImage == null;
		_ = actionValue == null;
		_ = battleAction == null;
		if (baseBattleActionData.EnableColorReference)
		{
			_ = baseBattleActionData.colorReference.Value;
		}
		else
		{
			_ = baseBattleActionData.ActionColor;
		}
		if (!battleAction.BattleActionSprite)
		{
			actionImage.sprite = baseBattleActionData.ActionSprite;
		}
		else
		{
			_ = battleAction.BattleActionSprite == null;
			actionImage.sprite = battleAction.BattleActionSprite;
		}
		if (compendiumItemState == CompendiumItemState.Discovered)
		{
			actionImage.color = (baseBattleActionData.ApplyColorToActionIcon ? defaultColor : Color.white);
		}
		else
		{
			actionImage.color = Color.black;
		}
		if (empowered)
		{
			actionAmount += "^";
		}
		if (compendiumItemState == CompendiumItemState.Discovered)
		{
			actionValue.color = defaultColor;
			actionValue.SetText(actionAmount);
		}
		else
		{
			actionValue.color = Color.black;
			actionValue.SetText("?");
		}
	}

	public void ToggleActionFace(bool toggle, Color disabledColor)
	{
		actionImage.color = ((!toggle) ? disabledColor : (battleAction.BaseBattleActionData.ApplyColorToActionIcon ? defaultColor : Color.white));
	}

	public void ToggleActionValue(bool toggle)
	{
		actionValue.gameObject.SetActive(toggle);
	}
}
